//! Display names (English / French) for the internal ids found in saves.
//!
//! Saves only contain internal ids (`SheepBall`, `BOSS_SheepBall`, passive
//! `Rare`…). Lookups are case-insensitive; an unknown id returns `None`, so the
//! caller can fall back to the raw id. The table is generated by
//! `scripts/gen_names.py`.

mod data;

use serde::{Deserialize, Serialize};

/// Language of a display name.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Lang {
    En,
    Fr,
}

fn find_pal(id: &str) -> Option<&'static (&'static str, &'static str, &'static str, &'static str, &'static str)> {
    let key = id.to_lowercase();
    data::PALS
        .binary_search_by(|row| row.0.cmp(key.as_str()))
        .ok()
        .map(|i| &data::PALS[i])
}

/// Name of a pal id as shown in game, variant title included
/// (`BOSS_SheepBall` → "Big Floof Lamball" / "Énorme et Moelleux Lamball").
pub fn pal_name(id: &str, lang: Lang) -> Option<&'static str> {
    find_pal(id).map(|row| match lang {
        Lang::En => row.3,
        Lang::Fr => row.4,
    })
}

/// Name of the base species of a pal id, without variant title
/// (`BOSS_SheepBall` → "Lamball"). Use it to group alphas with their species.
pub fn pal_species_name(id: &str, lang: Lang) -> Option<&'static str> {
    let family = find_pal(id)?.2;
    pal_name(family, lang)
}

/// Name of a passive skill id (`PassiveSkillList` entries of an `OwnedPal`).
pub fn passive_name(id: &str, lang: Lang) -> Option<&'static str> {
    let key = id.to_lowercase();
    data::PASSIVES
        .binary_search_by(|row| row.0.cmp(key.as_str()))
        .ok()
        .map(|i| match lang {
            Lang::En => data::PASSIVES[i].2,
            Lang::Fr => data::PASSIVES[i].3,
        })
}
